INSERT INTO objetivo_aprendizaje (id, unidad_id, codigo, descripcion, eje, texto_referencia) VALUES
    (1, 1, 'LE06 OA 01', 'Leer de manera fluida textos variados apropiados a su edad: pronunciando las palabras con precisión; respetando la prosodia indicada por todos los signos de puntuación; decodificando de manera automática la mayoría de las palabras del texto.', 'Lectura - Comprensión', NULL),
    (2, 1, 'LE06 OA 02', 'Comprender textos aplicando estrategias de comprensión lectora; por ejemplo: relacionar la información del texto con sus experiencias y conocimientos; releer lo que no fue comprendido; formular preguntas sobre lo leído y responderlas; organizar la información en esquemas o mapas conceptuales; resumir.', 'Lectura - Comprensión', NULL),
    (3, 1, 'LE06 OA 03', 'Leer y familiarizarse con un amplio repertorio de literatura para aumentar su conocimiento del mundo, desarrollar su imaginación y reconocer su valor social y cultural; por ejemplo: poemas, cuentos folclóricos y de autor, fábulas, leyendas, mitos, novelas, historietas, entre otros.', 'Lectura - Comprensión', NULL),
    (4, 1, 'LE06 OA 04', 'Analizar aspectos relevantes de las narraciones leídas para profundizar su comprensión: identificar las acciones principales del relato y explicar cómo influyen en el desarrollo de la historia; explicar las actitudes y reacciones de los personajes de acuerdo con sus motivaciones y las situaciones que viven; describir el ambiente y las costumbres representadas en el texto y explicar su influencia en las acciones del relato; relacionar el relato, si es pertinente, con la época y el lugar en que se ambienta; interpretar el lenguaje figurado; expresar opiniones sobre las actitudes y acciones de los personajes y fundamentarlas con ejemplos del texto; llegar a conclusiones sustentadas en la información del texto; comparar textos de autores diferentes y justificar su preferencia por alguno.', 'Lectura - Comprensión', NULL),
    (5, 1, 'LE06 OA 05', 'Analizar aspectos relevantes de diversos poemas para profundizar su comprensión: explicar cómo el lenguaje poético empleado por el autor apela a los sentidos, sugiere estados de ánimo y crea imágenes en el lector; identificar personificaciones, comparaciones e hipérboles y explicar su significado dentro del poema; analizar cómo los efectos sonoros (aliteración y onomatopeya) utilizados por el poeta refuerzan lo dicho.', 'Lectura - Comprensión', NULL),
    (6, 1, 'LE06 OA 06', 'Leer independientemente y comprender textos no literarios (cartas, biografías, relatos históricos, libros y artículos informativos, noticias, etc.) para ampliar su conocimiento del mundo y formarse una opinión: extraer información explícita e implícita; hacer inferencias a partir de la información del texto y de sus experiencias y conocimientos; relacionar la información de imágenes, gráficos, tablas, mapas o diagramas con el texto; interpretar expresiones en lenguaje figurado; comparar información entre dos textos del mismo tema; formular una opinión sobre algún aspecto de la lectura y fundamentarla con información del texto o conocimientos previos.', 'Lectura - Comprensión', NULL),
    (7, 1, 'LE06 OA 07', 'Evaluar críticamente la información presente en textos de diversa procedencia: determinar quién es el emisor, cuál es su propósito y a quién dirige el mensaje; evaluar si un texto entrega suficiente información para responder una pregunta o cumplir un propósito; comparar la información que se entrega sobre una misma noticia en distintas fuentes.', 'Lectura - Comprensión', NULL),
    (8, 1, 'LE06 OA 08', 'Sintetizar, registrar y ordenar las ideas principales de textos leídos para satisfacer propósitos como estudiar, hacer una investigación, recordar detalles, entre otros.', 'Lectura - Comprensión', NULL),
    (9, 1, 'LE06 OA 09', 'Desarrollar el gusto por la lectura, leyendo habitualmente diversos textos.', 'Lectura - Comprensión', NULL),
    (10, 1, 'LE06 OA 10', 'Asistir habitualmente a la biblioteca para satisfacer diversos propósitos (seleccionar textos, investigar sobre un tema, informarse sobre actualidad, etc.), adecuando su comportamiento y cuidando el material para permitir el trabajo y la lectura de los demás.', 'Lectura - Comprensión', NULL),
    (11, 1, 'LE06 OA 11', 'Buscar y comparar información sobre un tema, utilizando fuentes como internet, enciclopedias, libros y prensa, entre otras, para llevar a cabo una investigación.', 'Lectura - Comprensión', NULL),
    (12, 1, 'LE06 OA 12', 'Aplicar estrategias para determinar el significado de palabras nuevas: claves contextuales; raíces y afijos; preguntar a otro; diccionarios, enciclopedias e internet.', 'Lectura - Comprensión', NULL),
    (13, 2, 'LE06 OA 13', 'Escribir frecuentemente, para desarrollar la creatividad y expresar sus ideas, textos como poemas, diarios de vida, cuentos, anécdotas, cartas, blogs, entre otros.', 'Escritura - Producción', NULL),
    (14, 2, 'LE06 OA 14', 'Escribir creativamente narraciones (relatos de experiencias personales, noticias, cuentos, etc.) que tengan una estructura clara; utilicen conectores adecuados; tengan coherencia en sus oraciones; incluyan descripciones y diálogo (si es pertinente) que desarrollen la trama, los personajes y el ambiente.', 'Escritura - Producción', NULL),
    (15, 2, 'LE06 OA 15', 'Escribir artículos informativos para comunicar información sobre un tema: organizar el texto en una estructura clara; desarrollar una idea central por párrafo; agregar las fuentes utilizadas.', 'Escritura - Producción', NULL),
    (16, 2, 'LE06 OA 16', 'Escribir frecuentemente para compartir impresiones sobre sus lecturas, desarrollando un tema relevante del texto leído y fundamentando sus comentarios con ejemplos.', 'Escritura - Producción', NULL),
    (17, 2, 'LE06 OA 17', 'Planificar sus textos: establecer propósito y destinatario; generar ideas a partir de sus conocimientos e investigación; organizar las ideas que compondrán su escrito.', 'Escritura - Producción', NULL),
    (18, 2, 'LE06 OA 18', 'Escribir, revisar y editar sus textos para satisfacer un propósito y transmitir sus ideas con claridad. Durante este proceso: agregar ejemplos, datos y justificaciones para profundizar las ideas; emplear vocabulario preciso y variado y un registro adecuado; releer a medida que escriben; asegurar la coherencia y agregar conectores; editar en forma independiente aspectos de ortografía y presentación; utilizar herramientas del procesador de textos para buscar sinónimos, corregir ortografía y gramática y dar formato cuando escriben en computador.', 'Escritura - Producción', NULL),
    (19, 2, 'LE06 OA 19', 'Incorporar de manera pertinente en la escritura el vocabulario nuevo extraído de textos escuchados o leídos.', 'Escritura - Producción', NULL),
    (20, 2, 'LE06 OA 20', 'Ampliar su capacidad expresiva, utilizando los recursos que ofrece el lenguaje para expresar un mismo mensaje de diversas maneras; por ejemplo: sinónimos, hipónimos e hiperónimos, locuciones, comparaciones, entre otros.', 'Escritura - Producción', NULL),
    (21, 2, 'LE06 OA 21', 'Utilizar correctamente los participios irregulares (por ejemplo, roto, abierto, dicho, escrito, muerto, puesto, vuelto) en sus producciones escritas.', 'Escritura - Producción', NULL),
    (22, 2, 'LE06 OA 22', 'Escribir correctamente para facilitar la comprensión por parte del lector, aplicando todas las reglas de ortografía literal, acentual y puntual aprendidas en años anteriores, además de: escritura de los verbos haber, tener e ir en los tiempos más utilizados; coma en frases explicativas; coma en presencia de conectores que la requieren; acentuación de pronombres interrogativos y exclamativos.', 'Escritura - Producción', NULL),
    (23, 3, 'LE06 OA 23', 'Comprender y disfrutar versiones completas de obras de la literatura, narradas o leídas por un adulto, como cuentos folclóricos y de autor, poemas, mitos y leyendas, y capítulos de novelas.', 'Comunicación oral', NULL),
    (24, 3, 'LE06 OA 24', 'Comprender textos orales (explicaciones, instrucciones, noticias, documentales, entrevistas, testimonios, relatos, reportajes, etc.) para obtener información y desarrollar su curiosidad por el mundo: relacionar las ideas escuchadas con sus experiencias personales y conocimientos previos; extraer y registrar información relevante; formular preguntas para comprender o elaborar una idea o aclarar el significado de una palabra; comparar información dentro del texto o con otros textos; formular y fundamentar una opinión sobre lo escuchado; identificar diferentes puntos de vista.', 'Comunicación oral', NULL),
    (25, 3, 'LE06 OA 25', 'Evaluar críticamente mensajes publicitarios: identificar al emisor; explicar la intención del emisor; identificar a quién está dirigido el mensaje y fundamentar cómo llegaron a esa conclusión.', 'Comunicación oral', NULL),
    (26, 3, 'LE06 OA 26', 'Apreciar obras de teatro, películas o representaciones: discutir aspectos relevantes de la historia; describir cómo los actores cambian sus tonos de voz y su gestualidad para expresar diversas emociones; identificar recursos que buscan provocar un efecto en la audiencia, como efectos de sonido, música e iluminación.', 'Comunicación oral', NULL),
    (27, 3, 'LE06 OA 27', 'Dialogar para compartir y desarrollar ideas y buscar acuerdos: mantener el foco en un tema; complementar las ideas de otro y ofrecer sugerencias; aceptar sugerencias; hacer comentarios en los momentos adecuados; mostrar acuerdo o desacuerdo con respeto; fundamentar su postura.', 'Comunicación oral', NULL),
    (28, 3, 'LE06 OA 28', 'Interactuar de acuerdo con las convenciones sociales en diferentes situaciones: presentarse a sí mismo y a otros; saludar; preguntar; expresar opiniones, sentimientos e ideas; utilizar fórmulas de cortesía como por favor, gracias, perdón y permiso.', 'Comunicación oral', NULL),
    (29, 3, 'LE06 OA 29', 'Expresarse de manera clara y efectiva en exposiciones orales para comunicar temas de su interés: presentar ideas de manera coherente y cohesiva; fundamentar planteamientos con ejemplos y datos; organizar las ideas en introducción, desarrollo y cierre; usar elementos de cohesión; utilizar vocabulario variado y preciso y registro formal; emplear construcciones sintácticas variadas; conjugar correctamente los verbos y utilizar participios irregulares; pronunciar claramente y usar volumen audible, entonación, pausas y énfasis adecuados; usar gestos y posturas acordes; utilizar material de apoyo de manera efectiva; exponer sin leer de un texto escrito.', 'Comunicación oral', NULL),
    (30, 3, 'LE06 OA 30', 'Incorporar de manera pertinente en sus intervenciones orales el vocabulario nuevo extraído de textos escuchados o leídos.', 'Comunicación oral', NULL),
    (31, 3, 'LE06 OA 31', 'Producir textos orales espontáneos o planificados de diverso tipo para desarrollar su capacidad expresiva: poemas; narraciones (contar una historia, describir una actividad, relatar noticias o testimonios, etc.); dramatizaciones.', 'Comunicación oral', NULL),
    (32, 4, 'MA06 OA 01', 'Demostrar que comprenden los factores y múltiplos: determinar los múltiplos y factores de números naturales menores de 100; identificar números primos y compuestos; resolver problemas que involucran múltiplos.', 'Números y operaciones', NULL),
    (33, 4, 'MA06 OA 02', 'Realizar cálculos que involucren las cuatro operaciones en el contexto de la resolución de problemas, utilizando la calculadora en ámbitos superiores a 10 000.', 'Números y operaciones', NULL),
    (34, 4, 'MA06 OA 03', 'Demostrar que comprenden el concepto de razón de manera concreta, pictórica y simbólica, en forma manual y/o usando software educativo.', 'Números y operaciones', NULL),
    (35, 4, 'MA06 OA 04', 'Demostrar que comprenden el concepto de porcentaje de manera concreta, pictórica y simbólica, de forma manual y/o usando software educativo.', 'Números y operaciones', NULL),
    (36, 4, 'MA06 OA 05', 'Demostrar que comprenden las fracciones y números mixtos: identificar y determinar equivalencias entre fracciones impropias y números mixtos usando material concreto y representaciones pictóricas, de manera manual y/o con software educativo; representar estos números en la recta numérica.', 'Números y operaciones', NULL),
    (37, 4, 'MA06 OA 06', 'Resolver adiciones y sustracciones de fracciones propias e impropias y números mixtos con numeradores y denominadores de hasta dos dígitos.', 'Números y operaciones', NULL),
    (38, 4, 'MA06 OA 07', 'Demostrar que comprenden la multiplicación y la división de decimales por números naturales de un dígito, múltiplos de 10 y decimales hasta la milésima, de manera concreta, pictórica y simbólica.', 'Números y operaciones', NULL),
    (39, 4, 'MA06 OA 08', 'Resolver problemas rutinarios y no rutinarios que involucren adiciones y sustracciones de fracciones propias, impropias, números mixtos o decimales hasta la milésima.', 'Números y operaciones', NULL),
    (40, 5, 'MA06 OA 09', 'Demostrar que comprenden la relación entre los valores de una tabla y aplicarla en la resolución de problemas sencillos: identificar patrones entre los valores de la tabla; formular una regla con lenguaje matemático.', 'Patrones y álgebra', NULL),
    (41, 5, 'MA06 OA 10', 'Representar generalizaciones de relaciones entre números naturales, usando expresiones con letras y ecuaciones.', 'Patrones y álgebra', NULL),
    (42, 5, 'MA06 OA 11', 'Resolver ecuaciones de primer grado con una incógnita, utilizando estrategias como una balanza, la descomposición y la correspondencia uno a uno entre los términos en cada lado de la ecuación, y aplicando procedimientos formales de resolución.', 'Patrones y álgebra', NULL),
    (43, 6, 'MA06 OA 12', 'Construir y comparar triángulos de acuerdo con la medida de sus lados y/o sus ángulos con instrumentos geométricos o software geométrico.', 'Geometría', NULL),
    (44, 6, 'MA06 OA 13', 'Demostrar que comprenden el concepto de área de una superficie en cubos y paralelepípedos, calculando el área de sus redes (plantillas) asociadas.', 'Geometría', NULL),
    (45, 6, 'MA06 OA 14', 'Realizar teselados de figuras 2D usando traslaciones, reflexiones y rotaciones.', 'Geometría', NULL),
    (46, 6, 'MA06 OA 15', 'Construir ángulos agudos, obtusos, rectos, extendidos y completos con instrumentos geométricos o software geométrico.', 'Geometría', NULL),
    (47, 6, 'MA06 OA 16', 'Identificar los ángulos que se forman entre dos rectas que se cortan: pares de ángulos opuestos por el vértice y pares de ángulos complementarios.', 'Geometría', NULL),
    (48, 6, 'MA06 OA 17', 'Demostrar de manera concreta, pictórica y simbólica que la suma de los ángulos interiores de un triángulo es 180° y de un cuadrilátero es 360°.', 'Geometría', NULL),
    (49, 7, 'MA06 OA 18', 'Calcular la superficie de cubos y paralelepípedos expresando el resultado en cm² y m².', 'Medición', NULL),
    (50, 7, 'MA06 OA 19', 'Calcular el volumen de cubos y paralelepípedos, expresando el resultado en cm³, m³ y mm³.', 'Medición', NULL),
    (51, 7, 'MA06 OA 20', 'Estimar y medir ángulos usando el transportador, expresando las mediciones en grados.', 'Medición', NULL),
    (52, 7, 'MA06 OA 21', 'Calcular ángulos en rectas paralelas cortadas por una transversal y en triángulos.', 'Medición', NULL),
    (53, 8, 'MA06 OA 22', 'Comparar distribuciones de dos grupos, provenientes de muestras aleatorias, usando diagramas de puntos y de tallo y hojas.', 'Datos y probabilidades', NULL),
    (54, 8, 'MA06 OA 23', 'Conjeturar acerca de la tendencia de resultados obtenidos en repeticiones de un mismo experimento con dados, monedas u otros, de manera manual y/o usando software educativo.', 'Datos y probabilidades', NULL),
    (55, 8, 'MA06 OA 24', 'Leer e interpretar gráficos de barra doble y circulares y comunicar sus conclusiones.', 'Datos y probabilidades', NULL),
    (56, 9, 'CN06 OA 01', 'Explicar, a partir de una investigación experimental, los requerimientos de agua, dióxido de carbono y energía lumínica para la producción de azúcar y liberación de oxígeno en la fotosíntesis, comunicando sus resultados y los aportes de científicos en este campo a través del tiempo.', 'Ciencias de la Vida', NULL),
    (57, 9, 'CN06 OA 02', 'Representar, por medio de modelos, la transferencia de energía y materia desde los organismos fotosintéticos a otros seres vivos por medio de cadenas y redes alimentarias en diferentes ecosistemas.', 'Ciencias de la Vida', NULL),
    (58, 9, 'CN06 OA 03', 'Analizar los efectos de la actividad humana sobre las redes alimentarias.', 'Ciencias de la Vida', NULL),
    (59, 9, 'CN06 OA 04', 'Identificar y describir las funciones de las principales estructuras del sistema reproductor humano femenino y masculino.', 'Ciencias de la Vida', NULL),
    (60, 9, 'CN06 OA 05', 'Describir y comparar los cambios que se producen en la pubertad en mujeres y hombres, reconociéndola como una etapa del desarrollo humano.', 'Ciencias de la Vida', NULL),
    (61, 9, 'CN06 OA 06', 'Reconocer los beneficios de realizar actividad física en forma regular y de cuidar la higiene corporal en el período de la pubertad.', 'Ciencias de la Vida', NULL),
    (62, 9, 'CN06 OA 07', 'Investigar y comunicar los efectos nocivos de algunas drogas para la salud, proponiendo conductas de protección.', 'Ciencias de la Vida', NULL),
    (63, 10, 'CN06 OA 08', 'Explicar que la energía es necesaria para que los objetos cambien y los seres vivos realicen sus procesos vitales, y que la mayoría de los recursos energéticos proviene directa o indirectamente del Sol, dando ejemplos.', 'Ciencias Físicas y Químicas', NULL),
    (64, 10, 'CN06 OA 09', 'Investigar en forma experimental la transformación de la energía de una forma a otra, dando ejemplos y comunicando sus conclusiones.', 'Ciencias Físicas y Químicas', NULL),
    (65, 10, 'CN06 OA 10', 'Demostrar, por medio de la investigación experimental, que el calor fluye de un objeto caliente a uno frío hasta que ambos alcanzan la misma temperatura.', 'Ciencias Físicas y Químicas', NULL),
    (66, 10, 'CN06 OA 11', 'Clasificar los recursos naturales energéticos en no renovables y renovables y proponer medidas para el uso responsable de la energía.', 'Ciencias Físicas y Químicas', NULL),
    (67, 10, 'CN06 OA 12', 'Explicar, a partir de modelos, que la materia está formada por partículas en movimiento en sus estados sólido, líquido y gaseoso.', 'Ciencias Físicas y Químicas', NULL),
    (68, 10, 'CN06 OA 13', 'Demostrar, mediante la investigación experimental, los cambios de estado de la materia, como fusión, evaporación, ebullición, condensación, solidificación y sublimación.', 'Ciencias Físicas y Químicas', NULL),
    (69, 10, 'CN06 OA 14', 'Diferenciar entre calor y temperatura, considerando que el calor es una forma de energía y la temperatura es una medida de lo caliente de un objeto.', 'Ciencias Físicas y Químicas', NULL),
    (70, 10, 'CN06 OA 15', 'Medir e interpretar la información obtenida al calentar y enfriar el agua, considerando las transformaciones de un estado a otro.', 'Ciencias Físicas y Químicas', NULL),
    (71, 11, 'CN06 OA 16', 'Describir las características de las capas de la Tierra (atmósfera, litósfera e hidrósfera) que posibilitan el desarrollo de la vida y proveen recursos para el ser humano, y proponer medidas de protección de dichas capas.', 'Ciencias de la Tierra y el Universo', NULL),
    (72, 11, 'CN06 OA 17', 'Investigar experimentalmente la formación del suelo, sus propiedades (como color, textura y capacidad de retención de agua) y la importancia de protegerlo de la contaminación, comunicando sus resultados.', 'Ciencias de la Tierra y el Universo', NULL),
    (73, 11, 'CN06 OA 18', 'Explicar las consecuencias de la erosión sobre la superficie de la Tierra, identificando los agentes que la provocan, como el viento, el agua y las actividades humanas.', 'Ciencias de la Tierra y el Universo', NULL),
    (74, 12, 'HI06 OA 01', 'Explicar los múltiples antecedentes de la independencia de las colonias americanas y reconocer que la independencia de Chile se enmarca en un proceso continental.', 'Historia', NULL),
    (75, 12, 'HI06 OA 02', 'Explicar el desarrollo del proceso de independencia de Chile, considerando actores y bandos que se enfrentaron, hombres y mujeres destacados, avances y retrocesos de la causa patriota y acontecimientos significativos, como el cabildo abierto de 1810 y la formación de la Primera Junta Nacional de Gobierno, la elección del primer Congreso Nacional, las batallas de Rancagua, Chacabuco y Maipú y la Declaración de la Independencia, entre otros.', 'Historia', NULL),
    (76, 12, 'HI06 OA 03', 'Describir hitos y procesos de la organización de la república, incluyendo las dificultades y desafíos que implicó organizar en Chile una nueva forma de gobierno, el surgimiento de grupos con diferentes ideas políticas (conservadores y liberales), las características de la Constitución de 1833 y el impacto de las reformas realizadas por los liberales en la segunda mitad del siglo XIX.', 'Historia', NULL),
    (77, 12, 'HI06 OA 04', 'Investigar aspectos culturales del siglo XIX, como los avances en educación y la fundación de instituciones, el aporte de intelectuales y científicos nacionales (por ejemplo, Diego Barros Arana, Benjamín Vicuña Mackenna y José Victorino Lastarria) y extranjeros (por ejemplo, Andrés Bello, Claudio Gay, Charles Darwin y María Graham), las primeras mujeres en obtener títulos universitarios y el impacto de la llegada del ferrocarril y otros avances tecnológicos.', 'Historia', NULL),
    (78, 12, 'HI06 OA 05', 'Describir cómo se conformó el territorio de Chile durante el siglo XIX, considerando colonizaciones europeas, la incorporación de Isla de Pascua, la ocupación de la Araucanía, la Guerra del Pacífico y diversos conflictos bélicos, entre otros factores.', 'Historia', NULL),
    (79, 12, 'HI06 OA 06', 'Caracterizar los principales aspectos que definieron el período de riqueza aportada por la explotación del salitre, considerando la expansión económica y el inicio de la cuestión social.', 'Historia', NULL),
    (80, 12, 'HI06 OA 07', 'Explicar y dar ejemplos de la progresiva democratización de la sociedad durante el siglo XX, considerando el acceso creciente al voto, la participación de la mujer en la vida pública y el acceso a la educación y la cultura, entre otros.', 'Historia', NULL),
    (81, 12, 'HI06 OA 08', 'Comparar diferentes visiones sobre el quiebre de la democracia en Chile, el régimen o dictadura militar y el proceso de recuperación de la democracia a fines del siglo XX, considerando los distintos actores, experiencias y puntos de vista, y el consenso actual con respecto al valor de la democracia.', 'Historia', NULL),
    (82, 12, 'HI06 OA 09', 'Explicar y dar ejemplos de aspectos que se mantienen y aspectos que han cambiado o se han desarrollado en la sociedad chilena a lo largo de su historia.', 'Historia', NULL),
    (83, 13, 'HI06 OA 10', 'Identificar elementos constitutivos del territorio nacional, considerando la localización de Chile en el mundo y su carácter tricontinental.', 'Geografía', NULL),
    (84, 13, 'HI06 OA 11', 'Caracterizar geográficamente las regiones político-administrativas del país, destacando los rasgos físicos (como clima, relieve, hidrografía y vegetación) y humanos (como volumen y distribución de la población y actividades económicas) que les dan unidad.', 'Geografía', NULL),
    (85, 13, 'HI06 OA 12', 'Comparar diversos ambientes naturales en Chile (desértico, altiplánico, costero, mediterráneo, andino, frío y lluvioso, patagónico y polar), considerando las oportunidades y dificultades que presentan y cómo las personas las han aprovechado y superado para vivir y desarrollarse.', 'Geografía', NULL),
    (86, 13, 'HI06 OA 13', 'Explicar las principales características físicas, humanas y económicas de su región y de su localidad.', 'Geografía', NULL),
    (87, 13, 'HI06 OA 14', 'Explicar cómo han influido los desastres naturales en el desarrollo de Chile durante su historia reciente, dando ejemplos de nivel nacional y regional (sismos, volcanismo, sequía, inundaciones y derrumbes, entre otros).', 'Geografía', NULL),
    (88, 14, 'HI06 OA 15', 'Explicar algunos elementos fundamentales de la organización democrática de Chile, incluyendo la división de poderes del Estado, la representación mediante cargos de elección popular (concejales, alcaldes, diputados, senadores y Presidente) y la importancia de la participación ciudadana.', 'Formación ciudadana', NULL),
    (89, 14, 'HI06 OA 16', 'Reconocer que la Constitución Política de Chile establece la organización política del país y garantiza los derechos y las libertades de las personas, instaurando un sistema democrático.', 'Formación ciudadana', NULL),
    (90, 14, 'HI06 OA 17', 'Comprender que todas las personas tienen derechos que deben ser respetados por los pares, la comunidad y el Estado, lo que constituye la base para vivir en una sociedad justa, y dar como ejemplo algunos artículos de la Constitución y de la Declaración Universal de los Derechos Humanos.', 'Formación ciudadana', NULL),
    (91, 14, 'HI06 OA 18', 'Explicar que los derechos generan deberes y responsabilidades en las personas e instituciones, y lo importante que es cumplirlos para la convivencia social y el bien común.', 'Formación ciudadana', NULL),
    (92, 14, 'HI06 OA 19', 'Proponer y fundamentar distintas formas en que la sociedad puede proteger a las personas de situaciones en las que no se respetan sus derechos.', 'Formación ciudadana', NULL),
    (93, 14, 'HI06 OA 20', 'Demostrar actitudes cívicas con acciones en su vida diaria, como respetar a todas las personas (actuar considerando la igualdad de derechos y escuchar respetuosamente opiniones distintas); contribuir a la buena convivencia (proponer soluciones frente a problemas, usar el diálogo, alcanzar acuerdos y cooperar en metas comunes); actuar con honestidad y responsabilidad (decir la verdad, cumplir responsabilidades y evitar la copia textual y el plagio); cuidar y valorar el patrimonio y el medioambiente (participar en campañas de reciclaje y ahorrar luz, agua y gas en la casa y la escuela).', 'Formación ciudadana', NULL),
    (94, 14, 'HI06 OA 21', 'Trabajar en equipo de manera efectiva para llevar a cabo una investigación u otro proyecto, asignando y asumiendo roles, cumpliendo responsabilidades y tiempos acordados, escuchando argumentos, manifestando opiniones fundamentadas y llegando a un punto de vista común.', 'Formación ciudadana', NULL),
    (95, 14, 'HI06 OA 22', 'Participar en su comunidad, tomando parte en elecciones para una directiva de curso, evaluando las propuestas de los diferentes aspirantes y considerando la importancia de elegir personas responsables.', 'Formación ciudadana', NULL),
    (96, 14, 'HI06 OA 23', 'Participar, mediante acciones concretas, en proyectos que impliquen aportes dentro de la escuela, la comunidad y la sociedad, como voluntariado y ayuda social, ateniéndose a un plan y un presupuesto.', 'Formación ciudadana', NULL),
    (97, 14, 'HI06 OA 24', 'Opinar y argumentar con fundamentos sobre temas de la asignatura u otros.', 'Formación ciudadana', NULL),
    (98, 14, 'HI06 OA 25', 'Evaluar posibles soluciones frente a un problema o proyecto y justificar su elección.', 'Formación ciudadana', NULL),
    (99, 14, 'HI06 OA 26', 'Informarse y opinar sobre temas relevantes y de su interés en el país y el mundo (política, medioambiente, deporte, arte y música, entre otros) por medio de periódicos y TIC.', 'Formación ciudadana', NULL);
INSERT INTO contenido (id, oa_id, unidad_id, titulo, explicacion, ejemplos, instrucciones, orden, origen) VALUES
    (1, 2, 1, 'Estrategias de comprensión lectora', 'Comprender un texto requiere construir significado: conectar sus ideas con conocimientos previos, releer pasajes poco claros, formular preguntas y resumir la información central. Un esquema ayuda a separar las ideas principales de los detalles.', 'Al leer una noticia sobre el agua, se puede resumir la idea central y anotar dos datos que la apoyan.', 'Lee un texto breve. Formula una pregunta, responde con información del texto y escribe un resumen de dos oraciones.', 1, 'PROPIO'),
    (2, 15, 2, 'Escribir un artículo informativo', 'Un artículo informativo comunica datos sobre un tema. Debe tener una estructura clara, una idea central por párrafo y señalar las fuentes consultadas para que el lector pueda distinguir los datos de las opiniones.', 'Un artículo sobre los humedales puede presentar qué son, qué especies albergan y qué amenazas enfrentan, indicando de dónde se obtuvo la información.', 'Planifica un artículo de tres párrafos sobre un tema de interés. Escribe la idea central de cada párrafo y registra al menos una fuente.', 1, 'PROPIO'),
    (3, 27, 3, 'Dialogar y fundamentar ideas', 'Un diálogo productivo mantiene el foco del tema, escucha las ideas de otras personas, ofrece sugerencias y expresa acuerdos o desacuerdos con respeto. Fundamentar una postura implica explicar las razones que la apoyan.', 'En una conversación sobre cómo cuidar el patio, una propuesta puede justificarse con razones y complementarse con una idea de otro compañero.', 'Lee una situación de convivencia. Escribe una propuesta, una razón que la apoye y una respuesta respetuosa a una postura distinta.', 1, 'PROPIO'),
    (4, 35, 4, 'Comprender y calcular porcentajes', 'Un porcentaje expresa una cantidad como parte de 100. Puede representarse con una cuadrícula de cien partes, como fracción con denominador 100 o con un número seguido del símbolo %.', 'Si 25 de 100 casillas están marcadas, está representado el 25 %. En una encuesta de 20 estudiantes, 5 equivalen al 25 %.', 'Representa 10 %, 25 % y 50 % de una cuadrícula de cien. Luego resuelve un problema sencillo e indica cómo encontraste el resultado.', 1, 'PROPIO'),
    (5, 42, 5, 'Resolver ecuaciones de primer grado', 'Una ecuación expresa una igualdad que incluye un valor desconocido. Para mantener la igualdad, las operaciones realizadas a un lado deben conservar el equilibrio con el otro lado.', 'En x + 7 = 15, se resta 7 a ambos lados y se obtiene x = 8.', 'Resuelve una ecuación de primer grado usando una balanza o la operación inversa. Comprueba tu solución reemplazando la incógnita.', 1, 'PROPIO'),
    (6, 48, 6, 'Suma de ángulos interiores', 'La suma de los ángulos interiores de cualquier triángulo es 180°. En un cuadrilátero la suma es 360°. Estas relaciones permiten calcular un ángulo que falta cuando se conocen los demás.', 'Si dos ángulos de un triángulo miden 50° y 60°, el tercero mide 70° porque 180° − 50° − 60° = 70°.', 'Dibuja un triángulo y un cuadrilátero. Calcula un ángulo desconocido a partir de los otros ángulos y explica el procedimiento.', 1, 'PROPIO'),
    (7, 50, 7, 'Calcular el volumen de cuerpos geométricos', 'El volumen mide el espacio que ocupa un cuerpo. Para un cubo o paralelepípedo rectangular se multiplican largo, ancho y alto; la unidad se expresa en unidades cúbicas.', 'Una caja de 4 cm de largo, 3 cm de ancho y 2 cm de alto tiene un volumen de 4 × 3 × 2 = 24 cm³.', 'Calcula el volumen de una caja rectangular a partir de sus tres dimensiones. Incluye la unidad cúbica y explica qué representa.', 1, 'PROPIO'),
    (8, 55, 8, 'Interpretar gráficos de barras dobles y circulares', 'Los gráficos permiten representar y comparar datos. Un gráfico de barras dobles compara dos grupos; uno circular muestra cómo se distribuye un total en categorías. Las conclusiones deben apoyarse en los valores representados.', 'Un gráfico de barras dobles puede comparar libros leídos por dos cursos; un gráfico circular puede mostrar los medios de transporte usados por un grupo.', 'Observa un conjunto de datos y elige un gráfico adecuado. Escribe dos conclusiones que se puedan verificar con sus valores.', 1, 'PROPIO'),
    (9, 57, 9, 'Cadenas y redes alimentarias', 'La materia y la energía pasan de los organismos fotosintéticos a otros seres vivos a través de la alimentación. Las flechas de una cadena alimentaria indican la dirección de la transferencia de materia y energía.', 'Hierba → saltamontes → rana → culebra muestra una posible relación alimentaria en un ecosistema.', 'Construye una cadena alimentaria de un ecosistema, identifica al productor y explica qué podría ocurrir si uno de sus organismos disminuye.', 1, 'PROPIO'),
    (10, 69, 10, 'Diferenciar calor y temperatura', 'La temperatura indica qué tan caliente o frío está un cuerpo y se mide con un termómetro. El calor es energía que se transfiere entre cuerpos cuando existe una diferencia de temperatura; fluye del más caliente al más frío.', 'Una cuchara fría que se introduce en una bebida caliente recibe energía térmica y su temperatura aumenta.', 'Explica con un ejemplo la diferencia entre calor y temperatura. Identifica qué cuerpo entrega energía y cuál la recibe.', 1, 'PROPIO'),
    (11, 72, 11, 'Investigar las propiedades del suelo', 'El suelo se forma lentamente a partir de materiales minerales y materia orgánica. Sus propiedades, como textura, color y retención de agua, varían y afectan a los organismos que pueden vivir en él.', 'Dos muestras de suelo pueden tener distinto color y retener cantidades diferentes de agua.', 'Propón una comparación de muestras de suelo. Señala qué propiedad observarás, cómo registrarás los resultados y por qué es importante proteger el suelo.', 1, 'PROPIO'),
    (12, 75, 12, 'El proceso de independencia de Chile', 'La independencia de Chile fue un proceso con avances y retrocesos, protagonizado por distintos grupos y personas. Entre sus hitos están el cabildo abierto de 1810, la Primera Junta de Gobierno, las batallas de Rancagua, Chacabuco y Maipú y la Declaración de Independencia.', 'Una línea de tiempo permite ordenar los hitos y relacionarlos con los cambios en el control político del territorio.', 'Ordena tres hitos del proceso de independencia y explica por qué uno de ellos fue importante para la causa patriota.', 1, 'PROPIO'),
    (13, 85, 13, 'Ambientes naturales de Chile', 'Chile presenta ambientes naturales diversos, desde el desértico hasta el polar. Cada uno ofrece oportunidades y dificultades asociadas con el clima, el relieve, el agua y los recursos, que influyen en las formas de vida y las actividades humanas.', 'La escasez de agua del desierto exige estrategias de uso y abastecimiento diferentes de las de una zona fría y lluviosa.', 'Compara dos ambientes naturales de Chile. Describe una oportunidad, una dificultad y una forma en que las personas se adaptan a cada ambiente.', 1, 'PROPIO'),
    (14, 89, 14, 'Constitución y sistema democrático', 'La Constitución establece la organización política del país y reconoce derechos y libertades. En un sistema democrático, las instituciones deben actuar según las reglas vigentes y respetar los derechos de las personas.', 'Las normas que organizan los poderes públicos y protegen la libertad de expresión forman parte del marco constitucional.', 'Explica una función de la Constitución y menciona un derecho que debe protegerse en una democracia.', 1, 'PROPIO');
