INSERT INTO pregunta (id, actividad_id, unidad_id, oa_id, enunciado, criterio_respuesta, dificultad, orden) VALUES
    (1, 1, 1, 2, '¿Qué conviene hacer cuando una parte del texto no se comprende?', 'Indica una estrategia de comprensión lectora.', 'BAJA', 1),
    (2, 2, 1, 2, '¿Para qué sirve resumir un texto?', 'Relaciona el resumen con las ideas principales.', 'BAJA', 2),
    (3, 3, 1, 2, '¿Qué debe incluir un buen resumen?', 'Reconoce selección de información central.', 'MEDIA', 3),
    (4, 3, 1, 2, 'Si una respuesta no aparece escrita literalmente, ¿qué puede hacer el lector?', 'Explica que puede inferir a partir de pistas y conocimientos previos.', 'MEDIA', 4),
    (5, 3, 1, 2, '¿Cuál estrategia ayuda a comprobar una interpretación?', 'Selecciona una estrategia basada en evidencia textual.', 'ALTA', 5),
    (6, 4, 2, 15, '¿Qué propósito tiene un artículo informativo?', 'Distingue informar de narrar ficción.', 'BAJA', 1),
    (7, 5, 2, 15, '¿Qué conviene hacer antes de redactar?', 'Reconoce planificación y organización de ideas.', 'BAJA', 2),
    (8, 6, 2, 15, '¿Qué debe desarrollar cada párrafo del artículo?', 'Identifica la idea central de cada párrafo.', 'MEDIA', 3),
    (9, 6, 2, 15, '¿Por qué se registran las fuentes utilizadas?', 'Explica la función de las fuentes.', 'MEDIA', 4),
    (10, 6, 2, 15, '¿Cuál organización facilita la lectura de un artículo informativo?', 'Reconoce estructura y coherencia.', 'ALTA', 5),
    (11, 7, 3, 27, '¿Qué significa fundamentar una opinión durante un diálogo?', 'Señala que se deben entregar razones.', 'BAJA', 1),
    (12, 8, 3, 27, '¿Cuál es una forma respetuosa de disentir?', 'Propone desacuerdo respetuoso.', 'BAJA', 2),
    (13, 9, 3, 27, 'Durante una conversación grupal, ¿qué acción ayuda a construir acuerdos?', 'Reconoce escucha y complementariedad.', 'MEDIA', 3),
    (14, 9, 3, 27, '¿Qué demuestra que se mantiene el foco del diálogo?', 'Identifica contribuciones pertinentes al tema.', 'MEDIA', 4),
    (15, 9, 3, 27, '¿Qué recurso fortalece una propuesta en una discusión?', 'Incluye razones o ejemplos.', 'ALTA', 5),
    (16, 10, 4, 35, '¿Qué representa 25 %?', 'Interpreta porcentaje como parte de 100.', 'BAJA', 1),
    (17, 11, 4, 35, '¿Cuánto es el 50 % de 20?', 'Calcula la mitad de una cantidad.', 'BAJA', 2),
    (18, 12, 4, 35, 'En una encuesta de 100 personas, 30 prefieren leer. ¿Qué porcentaje corresponde?', 'Relaciona cantidad sobre 100 con porcentaje.', 'MEDIA', 3),
    (19, 12, 4, 35, '¿Qué representación corresponde al 25 % de una cuadrícula de 100 casillas?', 'Identifica 25 de 100 casillas.', 'MEDIA', 4),
    (20, 12, 4, 35, 'Una mochila cuesta $20 000 y tiene un descuento del 10 %. ¿Cuánto se descuenta?', 'Calcula 10 % de 20 000.', 'ALTA', 5),
    (21, 13, 5, 42, 'En x + 7 = 15, ¿qué valor tiene x?', 'Resuelve una ecuación aditiva simple.', 'BAJA', 1),
    (22, 14, 5, 42, '¿Qué operación deshace una suma de 6?', 'Reconoce operación inversa.', 'BAJA', 2),
    (23, 15, 5, 42, 'Si 3x = 18, ¿cuánto vale x?', 'Resuelve división para aislar la incógnita.', 'MEDIA', 3),
    (24, 15, 5, 42, '¿Qué debe hacerse para conservar la igualdad al resolver una ecuación?', 'Indica aplicar operaciones equivalentes a ambos lados.', 'MEDIA', 4),
    (25, 15, 5, 42, '¿Cómo se comprueba la solución de una ecuación?', 'Sustituye el valor y verifica la igualdad.', 'ALTA', 5),
    (26, 16, 6, 48, '¿Cuánto suman los ángulos interiores de un triángulo?', 'Recuerda la propiedad de los triángulos.', 'BAJA', 1),
    (27, 17, 6, 48, '¿Cuánto suman los ángulos interiores de un cuadrilátero?', 'Recuerda la propiedad de los cuadriláteros.', 'BAJA', 2),
    (28, 18, 6, 48, 'Un triángulo tiene ángulos de 50° y 60°. ¿Cuánto mide el tercero?', 'Calcula 180° menos los dos ángulos conocidos.', 'MEDIA', 3),
    (29, 18, 6, 48, 'Un cuadrilátero tiene tres ángulos de 90°, 80° y 100°. ¿Cuánto mide el cuarto?', 'Calcula el ángulo faltante a partir de 360°.', 'MEDIA', 4),
    (30, 18, 6, 48, '¿Qué propiedad permite hallar un ángulo faltante en un triángulo?', 'Expresa la suma constante de ángulos interiores.', 'ALTA', 5),
    (31, 19, 7, 50, '¿Qué mide el volumen de una caja?', 'Define volumen como espacio ocupado.', 'BAJA', 1),
    (32, 20, 7, 50, '¿Qué unidad corresponde al volumen?', 'Distingue unidades cúbicas.', 'BAJA', 2),
    (33, 21, 7, 50, 'Una caja mide 4 cm × 3 cm × 2 cm. ¿Cuál es su volumen?', 'Multiplica las tres dimensiones.', 'MEDIA', 3),
    (34, 21, 7, 50, '¿Qué dimensiones se multiplican para calcular el volumen de un paralelepípedo?', 'Identifica largo, ancho y alto.', 'MEDIA', 4),
    (35, 21, 7, 50, 'Una caja duplica su largo y mantiene ancho y alto. ¿Qué ocurre con su volumen?', 'Relaciona factor de escala lineal con volumen en ese eje.', 'ALTA', 5),
    (36, 22, 8, 55, '¿Qué permite comparar un gráfico de barras dobles?', 'Reconoce la comparación de dos grupos.', 'BAJA', 1),
    (37, 23, 8, 55, '¿Qué representa el total en un gráfico circular?', 'Interpreta las categorías como partes de un total.', 'BAJA', 2),
    (38, 24, 8, 55, '¿Qué debe apoyar una conclusión obtenida de un gráfico?', 'Basa la conclusión en los datos mostrados.', 'MEDIA', 3),
